SELECT  FROM t_account_entry WHERE posting_id IN
#{postingId}
ORDER BY posting_id, line_no

SELECT  FROM t_account_entry WHERE reverses_entry_id IN
#{entryId}
ORDER BY id

SELECT e.id, e.posting_id, e.line_no, e.account_id, e.entry_side, e.amount, e.fact_line_no, e.reverses_entry_id, e.create_time
FROM t_account_entry e JOIN t_account_posting p ON p.id = e.posting_id
WHERE e.account_id = #{accountId}
ORDER BY p.posting_sequence, e.line_no
LIMIT #{limit} OFFSET #{offset}
